import {buildWhatsAppParts} from './cart.mjs';
import {readInvoices,saveInvoice,deleteInvoice} from './invoice-store.mjs';
import {cleanReceipt,receiptErrors,receiptStatus,invoiceDate} from './invoice-core.mjs';
import {invoicePdf} from './invoice-pdf.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>new Intl.NumberFormat('en-US').format(n);let current=null,pads={},pdfUrl=null;
function toast(s){$('#invoiceToast').textContent=s;$('#invoiceToast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#invoiceToast').classList.remove('show'),4000);}
function render(){if(pdfUrl){URL.revokeObjectURL(pdfUrl);pdfUrl=null;}const list=readInvoices(),id=location.hash.slice(1);current=list.find(i=>i.id===id)||null;if(!current){$('#invoiceRoot').innerHTML=`<div class="history-head"><h1>فواتيري على هذا الجهاز</h1><p class="muted">فواتير الطلب وبيانات الاستلام التي حفظتها من هذا المتصفح.</p></div><p class="local-note">الحفظ محلي على هذا الجهاز فقط. حمّل PDF للاحتفاظ بنسخة ومشاركتها مع المستودع. مسح بيانات المتصفح يحذف الأرشيف المحلي.</p>${id?'<div class="invoice-error">هذه الفاتورة غير موجودة على هذا الجهاز. افتحها من الجهاز الذي أصدرها، أو استخدم نسخة PDF التي حمّلتها.</div>':''}${list.length?`<div class="history-list">${list.map(i=>`<article class="history-card"><div><h2>${esc(i.pharmacy.name)}</h2><p dir="ltr">${i.id}</p><p>${invoiceDate(i.createdAt)} · ${i.items.length} صنف · ${money(i.total)} ل.س</p><span class="status">${receiptStatus(i.receipt)}</span></div><div class="actions"><a class="btn primary" href="#${i.id}">عرض والتوقيع</a><button class="btn danger" data-delete="${i.id}">حذف من الجهاز</button></div></article>`).join('')}</div>`:'<div class="empty-invoices"><span>▤</span><h2>فاتورتك الأولى تبدأ من السلة</h2><p>اختر المنتجات، وأدخل اسم الصيدلية وعنوانها، ثم اضغط «إصدار الفاتورة».</p><a href="index.html#catalog" class="btn primary">تصفّح المنتجات</a></div>'}`;document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('هل حمّلت نسخة؟ سيُحذف هذا السجل من هذا الجهاز.')){try{deleteInvoice(b.dataset.delete);render();}catch{toast('تعذّر حذف السجل.');}}});return;}
const i=current,r=cleanReceipt(i.receipt);const wa=buildWhatsAppParts(Object.fromEntries(i.items.map(p=>[p.id,p.qty])),i.items.map(p=>({...p,price:p.unitPrice})),{pharmacy:i.pharmacy,invoiceId:i.id});$('#invoiceRoot').innerHTML=`<div class="toolbar"><a href="invoice.html" class="btn">← جميع فواتيري</a><div><a href="index.html?edit=${i.id}" class="btn">تعديل الطلب وإصدار نسخة جديدة</a><button id="printInvoice" class="btn">طباعة</button><button id="downloadPdf" class="btn primary">↓ تحميل PDF</button></div></div><p id="pdfReady" class="local-note" hidden></p><p class="local-note">هذه النسخة محفوظة على هذا الجهاز فقط. عند التسليم: اكتب الاسمين وتاريخ التسليم، وليوقّع كل طرف في خانته، ثم احفظ وحمّل PDF. يمكنك أيضًا طباعة الفاتورة والتوقيع يدويًا.</p><details class="invoice-share"><summary>إرسال بيانات الطلب إلى واتساب المستودع ↗</summary><p>رقم الفاتورة وبيانات الصيدلية والأصناف تُدرج في الرسالة. أرفق PDF يدويًا في واتساب إذا أردت إرسال الملف أيضًا.</p><div>${wa.map((p,n)=>`<a class="btn primary" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${wa.length===1?'فتح الطلب في واتساب':`فتح الجزء ${n+1} من ${wa.length}`}</a>`).join('')}</div></details><div id="receiptError" class="invoice-error" role="alert" hidden></div><article class="invoice-paper"><div class="paper-heading"><div><h1>مستودع العاصمة</h1><h2>فاتورة طلب مبدئية</h2><p>واتساب الطلبات: <b dir="ltr">+963967765704</b></p></div><div class="invoice-number"><b>${i.id}</b><time>${invoiceDate(i.createdAt)}</time><br><span class="status">تحتاج تأكيد المستودع</span></div></div><section class="pharmacy-box"><span class="label">الصيدلية الطالبة</span><h3>${esc(i.pharmacy.name)}</h3><p><strong>العنوان</strong>${esc([i.pharmacy.city,i.pharmacy.address].filter(Boolean).join(' - '))}</p>${i.pharmacy.phone?`<p><strong>الهاتف</strong><bdi>${esc(i.pharmacy.phone)}</bdi></p>`:''}${i.pharmacy.contact?`<p><strong>المسؤول</strong>${esc(i.pharmacy.contact)}</p>`:''}</section>${i.previousId?`<p class="revision-note">نسخة جديدة بدلًا من ${esc(i.previousId)} — توقيعات النسخة السابقة لا تنتقل إلى هذه النسخة.</p>`:''}<div class="table-scroll"><table><thead><tr><th>#</th><th>الصنف</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>${i.items.map((p,n)=>`<tr><td>${n+1}</td><td class="item-name"><strong>${esc(p.ar)}</strong><small lang="en" dir="ltr">${esc(p.en)} · ${p.id}</small></td><td class="num">${p.qty}</td><td class="num">${money(p.unitPrice)}</td><td class="num">${money(p.total)}</td></tr>`).join('')}</tbody></table></div><div class="totals"><span>الإجمالي التقديري<small>${i.items.length} صنف · ${i.count} قطعة</small></span><div><b>${money(i.total)}</b> <small>ل.س</small></div></div><p class="muted">الأسعار والتوفر تحتاج تأكيد المستودع. الإجمالي لا يشمل التوصيل. لا تُعد هذه الفاتورة إثباتًا للدفع.</p>${i.pharmacy.notes?`<p class="notes"><b>ملاحظات الطلب</b><br>${esc(i.pharmacy.notes)}</p>`:''}<section class="receipt"><h2>التسليم والاستلام</h2><p class="intro">تُملأ هذه الخانات عند تسليم المنتجات. تُترك فارغة عند إنشاء الطلب.</p><div class="receipt-fields"><label class="field">تاريخ التسليم<input id="receiptDate" type="date" value="${r.date}"><span class="print-value" data-print="receiptDate">${r.date||'........................'}</span></label><label class="field">ملاحظات الاستلام / النواقص أو المرتجعات<textarea id="receiptNotes" maxlength="300">${esc(r.notes)}</textarea><span class="print-value" data-print="receiptNotes">${esc(r.notes)||'........................'}</span></label></div><div class="signature-grid">${[['warehouse','ممثل المستودع / المُسلّم',r.warehouseName],['pharmacy','ممثل الصيدلية / المستلم',r.pharmacyName]].map(([key,title,name])=>`<div class="signature-box"><h3>${title}</h3><label class="field">الاسم<input id="${key}Name" maxlength="80" value="${esc(name)}" autocomplete="off"><span class="print-value" data-print="${key}Name">${esc(name)||'........................'}</span></label><canvas id="${key}Signature" width="1000" height="260" aria-label="خانة توقيع ${title}"></canvas><div class="signature-controls"><span>وقّع بالإصبع أو بالقلم داخل الإطار</span><button type="button" data-clear-signature="${key}">مسح التوقيع</button></div><p class="stamp">الختم: ................................</p></div>`).join('')}</div><p class="print-status" id="receiptStatus">${receiptStatus(r)}</p><div class="receipt-actions"><button class="btn primary" id="saveReceipt">حفظ بيانات التسليم والتوقيع</button><p>التوقيع يُدخل يدويًا، ولا يتحقق الموقع من هوية الموقّعين. تغيير بيانات الاستلام يمسح التوقيعات لتوقيعها مجددًا. تعديل المنتجات يُصدر فاتورة جديدة.</p></div></section><div class="invoice-footer">${i.id} · مستودع العاصمة · نسخة محلية لدى الصيدلية</div></article>`;
pads={warehouse:signaturePad($('#warehouseSignature'),r.warehouseSignature),pharmacy:signaturePad($('#pharmacySignature'),r.pharmacySignature)};document.querySelectorAll('[data-clear-signature]').forEach(b=>b.onclick=()=>pads[b.dataset.clearSignature].clear());document.querySelectorAll('.field input,.field textarea').forEach(el=>el.oninput=()=>{$('#pdfReady').hidden=true;const p=document.querySelector(`[data-print="${el.id}"]`);if(p)p.textContent=el.value||'........................';if(el.id==='warehouseName')pads.warehouse.clear();else if(el.id==='pharmacyName')pads.pharmacy.clear();else{pads.warehouse.clear();pads.pharmacy.clear();}});$('#saveReceipt').onclick=()=>{if(persistReceipt())toast('حُفظت بيانات التسليم على هذا الجهاز.');};$('#downloadPdf').onclick=async()=>{if(!persistReceipt())return;const b=$('#downloadPdf');b.disabled=true;b.textContent='جارٍ تجهيز PDF…';try{const blob=await invoicePdf(current);if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=URL.createObjectURL(blob);const ready=$('#pdfReady');ready.hidden=false;ready.textContent='ملف PDF جاهز. اضغط الرابط لحفظه، ثم أرفقه في واتساب إذا رغبت. ';const a=document.createElement('a');a.className='btn primary';a.href=pdfUrl;a.download=current.id+'.pdf';a.textContent='حفظ ملف PDF الجاهز ↓';ready.append(a);a.click();toast('ملف PDF جاهز للتحميل.');}catch{toast('تعذّر تحميل PDF. استخدم زر الطباعة للحفظ كـ PDF.');}finally{b.disabled=false;b.textContent='↓ تحميل PDF';}};$('#printInvoice').onclick=()=>{if(persistReceipt())window.print();};}
function persistReceipt(){const r=cleanReceipt({warehouseName:$('#warehouseName').value,pharmacyName:$('#pharmacyName').value,date:$('#receiptDate').value,notes:$('#receiptNotes').value,warehouseSignature:pads.warehouse.value(),pharmacySignature:pads.pharmacy.value(),updatedAt:new Date().toISOString()});const errors=receiptErrors(r);if(errors.length){$('#receiptError').hidden=false;$('#receiptError').textContent=errors.join(' ');$('#receiptError').scrollIntoView({block:'center',behavior:'smooth'});return false;}const updated={...current,receipt:r};try{saveInvoice(updated);current=updated;$('#receiptError').hidden=true;$('#receiptStatus').textContent=receiptStatus(r);return true;}catch(e){toast(e.message);return false;}}
function signaturePad(canvas,initial){const ctx=canvas.getContext('2d');let drawing=false,hasInk=false,original=initial||'',changed=false;ctx.strokeStyle='#183e34';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';const ready=initial?new Promise(resolve=>{const img=new Image();img.onload=()=>{if(!changed){ctx.drawImage(img,0,0,canvas.width,canvas.height);hasInk=true;}resolve();};img.onerror=resolve;img.src=initial;}):Promise.resolve();const point=e=>{const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];};canvas.onpointerdown=e=>{if(e.button!==0&&e.pointerType==='mouse')return;$('#pdfReady').hidden=true;e.preventDefault();changed=true;drawing=true;canvas.setPointerCapture(e.pointerId);const[x,y]=point(e);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+.2,y+.2);ctx.stroke();hasInk=true;};canvas.onpointermove=e=>{if(!drawing)return;e.preventDefault();const[x,y]=point(e);ctx.lineTo(x,y);ctx.stroke();};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;return{ready,value:()=>changed?(hasInk?canvas.toDataURL('image/png'):''):original,clear:()=>{$('#pdfReady').hidden=true;changed=true;drawing=false;hasInk=false;original='';ctx.clearRect(0,0,canvas.width,canvas.height);}};}
window.addEventListener('hashchange',render);render();
